-- ⚙️ SETUP — run this cell first.
-- Creates my_db and the demo table that every example below uses.
CREATE DATABASE IF NOT EXISTS my_db;
USE my_db;
DROP TABLE IF EXISTS demo;
CREATE TABLE demo (
  id INTEGER, name TEXT, category TEXT, city TEXT,
  amount REAL, qty INTEGER, score REAL,
  created_at DATE, updated_at DATE, due_date DATE,
  is_active INTEGER, notes TEXT
);
INSERT INTO demo (id, name, category, city, amount, qty, score, created_at, updated_at, due_date, is_active, notes) VALUES
  (1, 'Aisyah Rahman', 'Retail', 'Kuala Lumpur', 1520.75, 3, 88.5, '2024-01-15', '2024-06-01', '2026-03-31', 1, 'VIP client'),
  (2, 'Budi Santoso', 'Corporate', 'Johor Bahru', 9800.00, 12, 72.0, '2023-11-02', '2024-05-20', '2026-04-30', 1, NULL),
  (3, 'Chen Wei', 'Retail', 'Penang', 340.50, 1, 65.25, '2024-03-10', '2024-04-18', '2026-02-28', 0, 'Follow up'),
  (4, 'Devi Kumar', 'SME', 'Ipoh', 5600.00, 7, 91.0, '2022-07-21', '2024-06-15', '2026-05-31', 1, NULL),
  (5, 'Emily Tan', 'Corporate', 'Kuala Lumpur', 12040.25, 20, 84.75, '2023-02-14', '2024-03-30', '2026-01-31', 1, 'Key account'),
  (6, 'Faisal Idris', 'Retail', 'Melaka', 780.00, 2, 58.0, '2024-05-05', '2024-05-25', '2026-06-30', 0, NULL),
  (7, 'Grace Lim', 'SME', 'Penang', 3300.90, 5, 77.5, '2023-09-19', '2024-06-10', '2026-03-15', 1, 'Renewal'),
  (8, 'Hafiz Omar', 'Corporate', 'Johor Bahru', 8750.00, 15, 69.0, '2022-12-01', '2024-02-28', '2026-04-20', 1, NULL),
  (9, 'Iman Yusof', 'Retail', 'Ipoh', 210.40, 1, 95.0, '2024-06-01', '2024-06-20', '2026-07-31', 1, 'New'),
  (10, 'Jason Ng', 'SME', 'Kuala Lumpur', 4600.00, 9, 80.25, '2023-04-27', '2024-05-11', '2026-05-15', 0, 'Overdue');
SELECT * FROM demo;

USE my_db;
-- ASCII: Returns the ASCII code value of the leftmost character.
SELECT id, ASCII(name) AS ex_1, ASCII(category) AS ex_2, ASCII(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CHAR: Converts an integer ASCII code to a character.
SELECT id, CHAR(65) AS ex_1, CHAR(66) AS ex_2, CHAR(67) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CHARINDEX: Returns the starting position of a substring.
SELECT id, CHARINDEX('a', name) AS ex_1, CHARINDEX('a', category) AS ex_2, CHARINDEX('a', city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CONCAT: Concatenates values into a single string.
SELECT id, CONCAT(name, '-', id) AS ex_1, CONCAT(category, '-', id) AS ex_2, CONCAT(city, '-', id) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CONCAT_WS: Concatenates values using a separator.
SELECT id, CONCAT_WS('/', name, category) AS ex_1, CONCAT_WS('/', category, category) AS ex_2, CONCAT_WS('/', city, category) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATALENGTH: Returns the number of bytes used to represent an expression.
SELECT id, DATALENGTH(name) AS ex_1, DATALENGTH(category) AS ex_2, DATALENGTH(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DIFFERENCE: Compares Soundex values and returns similarity score.
SELECT id, DIFFERENCE(name, city) AS ex_1, DIFFERENCE(category, city) AS ex_2, DIFFERENCE(city, city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- FORMAT: Returns a value formatted with the specified format string.
SELECT id, FORMAT(amount, 'N0') AS ex_1, FORMAT(amount, 'N1') AS ex_2, FORMAT(amount, 'N2') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LEFT: Returns the left part of a string.
SELECT id, LEFT(name, 3) AS ex_1, LEFT(category, 3) AS ex_2, LEFT(city, 3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LEN: Returns the number of characters in a string.
SELECT id, LEN(name) AS ex_1, LEN(category) AS ex_2, LEN(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LOWER: Converts string to lowercase.
SELECT id, LOWER(name) AS ex_1, LOWER(category) AS ex_2, LOWER(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LTRIM: Removes leading spaces from a string.
SELECT id, LTRIM(name) AS ex_1, LTRIM(category) AS ex_2, LTRIM(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- NCHAR: Returns the Unicode character specified by integer code.
SELECT id, NCHAR(9731) AS ex_1, NCHAR(9732) AS ex_2, NCHAR(9733) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- PATINDEX: Returns the starting position of a pattern.
SELECT id, PATINDEX('%a%', name) AS ex_1, PATINDEX('%a%', category) AS ex_2, PATINDEX('%a%', city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- QUOTENAME: Returns a Unicode string with delimiters for identifiers.
SELECT id, QUOTENAME(name) AS ex_1, QUOTENAME(category) AS ex_2, QUOTENAME(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- REPLACE: Replaces occurrences of a substring.
SELECT id, REPLACE(name, 'a', 'X') AS ex_1, REPLACE(category, 'a', 'X') AS ex_2, REPLACE(city, 'a', 'X') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- REPLICATE: Repeats a string a specified number of times.
SELECT id, REPLICATE(SUBSTRING(name, 1, 1), 3) AS ex_1, REPLICATE(SUBSTRING(category, 1, 1), 3) AS ex_2, REPLICATE(SUBSTRING(city, 1, 1), 3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- REVERSE: Reverses string characters.
SELECT id, REVERSE(name) AS ex_1, REVERSE(category) AS ex_2, REVERSE(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- RIGHT: Returns the right part of a string.
SELECT id, RIGHT(name, 3) AS ex_1, RIGHT(category, 3) AS ex_2, RIGHT(city, 3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- RTRIM: Removes trailing spaces from a string.
SELECT id, RTRIM(name) AS ex_1, RTRIM(category) AS ex_2, RTRIM(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SOUNDEX: Returns the Soundex code of a string.
SELECT id, SOUNDEX(name) AS ex_1, SOUNDEX(category) AS ex_2, SOUNDEX(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SPACE: Returns a string of repeated spaces.
SELECT id, ('[' || SPACE(1) || ']') AS ex_1, ('[' || SPACE(2) || ']') AS ex_2, ('[' || SPACE(3) || ']') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- STR: Converts numeric expression to character data.
SELECT id, STR(amount) AS ex_1, STR(qty) AS ex_2, STR(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- STUFF: Deletes part of a string and inserts another string.
SELECT id, STUFF(name, 1, 2, '**') AS ex_1, STUFF(category, 1, 2, '**') AS ex_2, STUFF(city, 1, 2, '**') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SUBSTRING: Extracts part of a string from a position.
SELECT id, SUBSTRING(name, 1, 3) AS ex_1, SUBSTRING(category, 1, 3) AS ex_2, SUBSTRING(city, 1, 3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- TRANSLATE: Replaces characters one-to-one from source to target set.
SELECT id, TRANSLATE(name, 'ae', 'AE') AS ex_1, TRANSLATE(category, 'ae', 'AE') AS ex_2, TRANSLATE(city, 'ae', 'AE') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- TRIM: Removes leading and trailing spaces or characters.
SELECT id, TRIM(name) AS ex_1, TRIM(category) AS ex_2, TRIM(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- UNICODE: Returns Unicode integer value of first character.
SELECT id, UNICODE(name) AS ex_1, UNICODE(category) AS ex_2, UNICODE(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- UPPER: Converts string to uppercase.
SELECT id, UPPER(name) AS ex_1, UPPER(category) AS ex_2, UPPER(city) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ABS: Returns absolute value.
SELECT id, ABS(amount) AS ex_1, ABS(qty) AS ex_2, ABS(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ACOS: Returns arccosine in radians.
SELECT id, ACOS(1) AS ex_1, ACOS(0.5) AS ex_2, ACOS(0) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ASIN: Returns arcsine in radians.
SELECT id, ASIN(1) AS ex_1, ASIN(0.5) AS ex_2, ASIN(0) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ATAN: Returns arctangent in radians.
SELECT id, ATAN(0.5) AS ex_1, ATAN(1) AS ex_2, ATAN(2) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ATN2: Returns arctangent of Y/X in radians.
SELECT id, ATN2(1.0, 2.0) AS ex_1, ATN2(2.0, 2.0) AS ex_2, ATN2(3.0, 2.0) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- AVG: Returns average value.
SELECT AVG(amount) AS by_amount, AVG(qty) AS by_qty, AVG(score) AS by_score FROM demo;

USE my_db;
-- CEILING: Returns smallest integer >= expression.
SELECT id, CEILING(amount) AS ex_1, CEILING(qty) AS ex_2, CEILING(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- COUNT: Returns row count.
SELECT COUNT(*) AS all_rows, COUNT(notes) AS non_null_notes, COUNT(DISTINCT category) AS distinct_categories FROM demo;

USE my_db;
-- COS: Returns cosine in radians.
SELECT id, COS(0) AS ex_1, COS(1) AS ex_2, COS(2) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- COT: Returns cotangent in radians.
SELECT id, COT(1) AS ex_1, COT(2) AS ex_2, COT(3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DEGREES: Converts radians to degrees.
SELECT id, DEGREES(1) AS ex_1, DEGREES(2) AS ex_2, DEGREES(3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- EXP: Returns e raised to expression.
SELECT id, EXP(1) AS ex_1, EXP(2) AS ex_2, EXP(3) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- FLOOR: Returns largest integer <= expression.
SELECT id, FLOOR(amount) AS ex_1, FLOOR(qty) AS ex_2, FLOOR(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LOG: Returns natural logarithm or logarithm with base.
SELECT id, LOG(amount + 1) AS ex_1, LOG(qty + 1) AS ex_2, LOG(score + 1) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LOG10: Returns base-10 logarithm.
SELECT id, LOG10(amount + 1) AS ex_1, LOG10(qty + 1) AS ex_2, LOG10(score + 1) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- MAX: Returns maximum value.
SELECT MAX(amount) AS by_amount, MAX(qty) AS by_qty, MAX(score) AS by_score FROM demo;

USE my_db;
-- MIN: Returns minimum value.
SELECT MIN(amount) AS by_amount, MIN(qty) AS by_qty, MIN(score) AS by_score FROM demo;

USE my_db;
-- PI: Returns the PI constant.
SELECT PI() AS value, name FROM demo LIMIT 3;

USE my_db;
-- POWER: Returns expression raised to power y.
SELECT id, POWER(amount, 2) AS ex_1, POWER(qty, 2) AS ex_2, POWER(score, 2) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- RADIANS: Converts degrees to radians.
SELECT id, RADIANS(30) AS ex_1, RADIANS(60) AS ex_2, RADIANS(90) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- RAND: Returns pseudo-random float from 0 to 1.
SELECT RAND() AS value, name FROM demo LIMIT 3;

USE my_db;
-- ROUND: Rounds numeric expression.
SELECT id, ROUND(amount, 1) AS ex_1, ROUND(qty, 1) AS ex_2, ROUND(score, 1) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SIGN: Returns sign: -1, 0, or 1.
SELECT id, SIGN(amount - 100) AS ex_1, SIGN(qty - 100) AS ex_2, SIGN(score - 100) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SIN: Returns sine in radians.
SELECT id, SIN(0) AS ex_1, SIN(1) AS ex_2, SIN(2) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SQRT: Returns square root.
SELECT id, SQRT(ABS(amount)) AS ex_1, SQRT(ABS(qty)) AS ex_2, SQRT(ABS(score)) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SQUARE: Returns square of expression.
SELECT id, SQUARE(amount) AS ex_1, SQUARE(qty) AS ex_2, SQUARE(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SUM: Returns sum of values.
SELECT SUM(amount) AS by_amount, SUM(qty) AS by_qty, SUM(score) AS by_score FROM demo;

USE my_db;
-- TAN: Returns tangent in radians.
SELECT id, TAN(amount) AS ex_1, TAN(qty) AS ex_2, TAN(score) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CURRENT_TIMESTAMP: Returns current date and time.
SELECT CURRENT_TIMESTAMP AS value, name FROM demo LIMIT 3;

USE my_db;
-- DATEADD: Adds interval to date.
SELECT id, DATEADD('month', 1, created_at) AS ex_1, DATEADD('month', 1, updated_at) AS ex_2, DATEADD('month', 1, due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATEDIFF: Returns date difference for given datepart.
SELECT id, DATEDIFF('day', created_at, due_date) AS ex_1, DATEDIFF('day', updated_at, due_date) AS ex_2, DATEDIFF('day', due_date, due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATEFROMPARTS: Builds a date from year/month/day.
SELECT id, DATEFROMPARTS(2026, 1, 15) AS ex_1, DATEFROMPARTS(2026, 2, 15) AS ex_2, DATEFROMPARTS(2026, 3, 15) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATENAME: Returns character string for datepart.
SELECT id, DATENAME('month', created_at) AS ex_1, DATENAME('month', updated_at) AS ex_2, DATENAME('month', due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATEPART: Returns integer datepart.
SELECT id, DATEPART('year', created_at) AS ex_1, DATEPART('year', updated_at) AS ex_2, DATEPART('year', due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DAY: Returns day of month.
SELECT id, DAY(created_at) AS ex_1, DAY(updated_at) AS ex_2, DAY(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- GETDATE: Returns current server date/time.
SELECT GETDATE() AS value, name FROM demo LIMIT 3;

USE my_db;
-- GETUTCDATE: Returns current UTC date/time.
SELECT GETUTCDATE() AS value, name FROM demo LIMIT 3;

USE my_db;
-- ISDATE: Returns whether expression can be interpreted as date.
SELECT id, ISDATE(created_at) AS ex_1, ISDATE(updated_at) AS ex_2, ISDATE(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- MONTH: Returns month part as integer.
SELECT id, MONTH(created_at) AS ex_1, MONTH(updated_at) AS ex_2, MONTH(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- SYSDATETIME: Returns current date/time with higher precision.
SELECT SYSDATETIME() AS value, name FROM demo LIMIT 3;

USE my_db;
-- YEAR: Returns year part as integer.
SELECT id, YEAR(created_at) AS ex_1, YEAR(updated_at) AS ex_2, YEAR(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- TO_DATE: Parses a string/serial into an ISO date. Optional Oracle-style format mask (YYYY, MM, DD, MON).
SELECT id, TO_DATE(created_at) AS ex_1, TO_DATE(updated_at) AS ex_2, TO_DATE(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- TO_CHAR: Formats a date or number as text using a format mask.
SELECT id, TO_CHAR(created_at, 'YYYY-MM-DD') AS ex_1, TO_CHAR(updated_at, 'YYYY-MM-DD') AS ex_2, TO_CHAR(due_date, 'YYYY-MM-DD') AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DATEADD: Adds an interval to a date.
SELECT id, DATEADD('month', 1, created_at) AS ex_1, DATEADD('month', 1, updated_at) AS ex_2, DATEADD('month', 1, due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- ADD_MONTHS: Adds n months to a date (Oracle style).
SELECT id, ADD_MONTHS(created_at, 2) AS ex_1, ADD_MONTHS(updated_at, 2) AS ex_2, ADD_MONTHS(due_date, 2) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- LAST_DAY: Returns the last day of the month for the given date.
SELECT id, LAST_DAY(created_at) AS ex_1, LAST_DAY(updated_at) AS ex_2, LAST_DAY(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- EOMONTH: Returns the last day of the month, with optional offset.
SELECT id, EOMONTH(created_at) AS ex_1, EOMONTH(updated_at) AS ex_2, EOMONTH(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- MONTHNAME: Returns the full month name (e.g. April).
SELECT id, MONTHNAME(created_at) AS ex_1, MONTHNAME(updated_at) AS ex_2, MONTHNAME(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- DAYNAME: Returns the full weekday name (e.g. Wednesday).
SELECT id, DAYNAME(created_at) AS ex_1, DAYNAME(updated_at) AS ex_2, DAYNAME(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- QUARTER: Returns the calendar quarter (1-4).
SELECT id, QUARTER(created_at) AS ex_1, QUARTER(updated_at) AS ex_2, QUARTER(due_date) AS ex_3 FROM demo LIMIT 5;

USE my_db;
-- CAST: Converts expression to target type.
SELECT CAST(amount AS INTEGER) AS to_int, CAST(qty AS REAL) AS to_real, CAST(id AS TEXT) AS to_text FROM demo LIMIT 5;

USE my_db;
-- COALESCE: Returns first non-null expression.
SELECT COALESCE(notes, 'n/a') AS c1, COALESCE(notes, city) AS c2, COALESCE(NULL, category, 'x') AS c3 FROM demo LIMIT 5;

USE my_db;
-- CONVERT: Converts expression to target type.
SELECT CONVERT(INTEGER, amount) AS c1, CONVERT(TEXT, qty) AS c2, CONVERT(TEXT, created_at) AS c3 FROM demo LIMIT 5; -- CONVERT support varies by engine

USE my_db;
-- CURRENT_USER: Returns current user name.
-- CURRENT_USER is a SQL Server keyword (no equivalent in SQLite). Use USER_NAME():
SELECT USER_NAME() AS current_user;

USE my_db;
-- IIF: Returns one of two values based on condition.
SELECT IIF(score >= 80, 'HIGH', 'LOW') AS c1, IIF(amount > 5000, 'BIG', 'SMALL') AS c2, IIF(is_active = 1, 'YES', 'NO') AS c3 FROM demo LIMIT 5;

USE my_db;
-- ISNULL: Replaces NULL with replacement value.
SELECT ISNULL(notes, 'n/a') AS c1, ISNULL(notes, city) AS c2, ISNULL(NULL, 0) AS c3 FROM demo LIMIT 5;

USE my_db;
-- ISNUMERIC: Returns whether expression is a valid numeric type.
SELECT ISNUMERIC(amount) AS c1, ISNUMERIC(name) AS c2, ISNUMERIC(qty) AS c3 FROM demo LIMIT 5; -- ISNUMERIC support varies by engine

USE my_db;
-- NULLIF: Returns NULL when two expressions are equal.
SELECT NULLIF(category, 'Retail') AS c1, NULLIF(qty, 1) AS c2, NULLIF(city, 'Ipoh') AS c3 FROM demo LIMIT 5;

USE my_db;
-- SESSION_USER: Returns session user.
-- SESSION_USER is a SQL Server keyword (no equivalent in SQLite). Use USER_NAME():
SELECT USER_NAME() AS session_user;

USE my_db;
-- SESSIONPROPERTY: Returns session-level setting value.
-- SESSIONPROPERTY is SQL Server-specific and not supported in this SQLite workspace.
SELECT NULL AS ansi_nulls;

USE my_db;
-- SYSTEM_USER: Returns system user name.
-- SYSTEM_USER is a SQL Server keyword (no equivalent in SQLite). Use USER_NAME():
SELECT USER_NAME() AS system_user;

USE my_db;
-- USER_NAME: Returns user name from user identifier.
SELECT USER_NAME() AS user_name;

