USE my_db;
SELECT * FROM demo;
SELECT id, name, city FROM demo;
SELECT name, amount FROM demo;

USE my_db;
SELECT DISTINCT category FROM demo;
SELECT DISTINCT city FROM demo;
SELECT DISTINCT category, city FROM demo;

