SELECT * FROM demo WHERE amount > 2000;
SELECT * FROM demo WHERE city = 'Kuala Lumpur';

USE my_db;
SELECT * FROM demo ORDER BY amount DESC;
SELECT * FROM demo ORDER BY created_at ASC;
SELECT * FROM demo ORDER BY name;

